 public BusinessHttpServer(InetSocketAddress address,String token,TaskApplicationService app,ObjectMapper mapper,GuiHttpAdapter gui) throws IOException {this(address,token,app,mapper,gui,com.sage.business.code.bootstrap.MultiClientSettings.defaults());}
 /* Design 10 §5.2: -Ddeployment.profile=container opts into non-loopback
  * binds — the compose network boundary replaces the loopback boundary. */
 private static boolean containerBindAllowed(InetSocketAddress address) {return "container".equalsIgnoreCase(System.getProperty("deployment.profile",""))||address.getAddress().isLoopbackAddress();}
 public BusinessHttpServer(InetSocketAddress address,String token,TaskApplicationService app,ObjectMapper mapper,GuiHttpAdapter gui,com.sage.business.code.bootstrap.MultiClientSettings settings) throws IOException {if(address==null||!containerBindAllowed(address))throw new IllegalArgumentException("Business service may only bind loopback outside -Ddeployment.profile=container");if(token==null||token.trim().length()<16)throw new IllegalArgumentException("A local bearer token is required");if(settings==null)throw new IllegalArgumentException("multi-client settings are required");this.server=HttpServer.create(address,0);this.token=token;this.app=app;this.mapper=mapper;this.gui=gui;this.clientSessions=null;this.registrationRequiredForMutation=false;/* Long requests are admitted separately; the validated worker reserve keeps short requests from being starved by streams and long-polls. */this.httpExecutor=new ThreadPoolExecutor(settings.getHttpWorkers(),settings.getHttpWorkers(),30L,TimeUnit.SECONDS,new ArrayBlockingQueue<Runnable>(settings.getHttpQueueCapacity()),Executors.defaultThreadFactory(),new ThreadPoolExecutor.AbortPolicy());((ThreadPoolExecutor)this.httpExecutor).allowCoreThreadTimeOut(true);server.setExecutor(httpExecutor);server.createContext("/health/live",new Handler());server.createContext("/health/ready",new Handler());server.createContext("/api/v1",new Handler());GuiStaticHandler staticHandler=new GuiStaticHandler();server.createContext("/ui",staticHandler);server.createContext("/",staticHandler);}
