 public BusinessHttpServer(InetSocketAddress address,String token,TaskApplicationService app,ObjectMapper mapper,GuiHttpAdapter gui,com.sage.business.code.application.parallel.ParallelPlanApplicationService parallel,com.sun.net.httpserver.HttpHandler v2,com.sage.business.code.application.ExecutionEnvironmentService sandbox,com.sage.business.code.application.client.ClientSessionRegistry clientSessions,boolean registrationRequiredForMutation) throws IOException {this(address,token,app,mapper,gui,parallel,v2,sandbox,com.sage.business.code.bootstrap.MultiClientSettings.defaults());this.clientSessions=clientSessions;this.registrationRequiredForMutation=registrationRequiredForMutation;}
